DateTime? parseDate(String date) {
  if (date.isEmpty || !RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(date)) return null;

  final parts = date.split('-');
  try {
    DateTime d = DateTime(int.parse(parts[0]), int.parse(parts[1]), int.parse(parts[2]));
    return d.isUtc ? d : DateTime.utc(d.year, d.month, d.day);
  } catch (_) {}
  return null;
}

