List<int> primeFactorization(int n) {
  List<int> factors = [];
  while (n % 2 == 0) {
    factors.add(2);
    n ~/= 2;
  }
  var divisor = 3;
  while (divisor * divisor <= n) {
    while (n % divisor == 0) {
      factors.add(divisor);
      n ~/= divisor;
    }
    divisor += 2;
  }
  if (n > 1) factors.add(n);
  return factors;
}

