String _convertToBase3(int num) {
  StringBuffer buffer = StringBuffer();
  while (num > 2) {
    buffer.insert(0, (num % 3).toString());
    num ~/= 3;
  }
  buffer.insert(0, num.toString());
  return buffer.toString();
}

