int _countPaths(int rows, int columns) {
  if (rows == 1 || columns == 1) return 1;
  var total = 0;
  for (var r = 1; r < rows - 1; ++r) {
    total += _countPaths(r, columns - 1) * _countPaths(rows - r, columns - 1);
  }
  return total + _countPaths(rows - 1, columns);
}

