  double Function(double) fp,
  double lower,
  double upper,
  int steps,
  double acc,
) {
  double h = 0.1;
  double h0 = (upper - lower) / 2.0;
  double h1 = (lower + upper) / 2.0;
  double rr = 0.0;
  for (int k = 1; k <= steps; ++k) {
    double ro = rr;
    int n = (1 << k) - 1;
    double ss = 0.0;
    for (int i = -n; i <= n; ++i) {
