class BipartiteGraph {
  final int leftSize;
  final int rightSize;

  List<List<int>> leftEdges = []; // Each sublist contains neighbors in the right set
  List<List<int>> rightEdges = []; // Each sublist contains neighbors in the left set

  BipartiteGraph(int leftCount, int rightCount)
      : leftSize = leftCount,
        rightSize = rightCount {
    for (int i = 0; i < leftCount; i++) {
      leftEdges.add([]);
    }
    for (int j = 0; j < rightCount; j++) {
      rightEdges.add([]);
    }
  }

  void addEdge(int leftNode, int rightNode) {
    if (leftNode >= 0 && leftNode < leftSize &&
        rightNode >= 0 && rightNode < rightSize) {
      leftEdges[leftNode].add(rightNode);
      rightEdges[rightNode].add(leftNode);
    } else {
      throw ArgumentError('Invalid node indices');
    }
  }

  bool isBipartite() {
    final visitedLeft = [false] * leftSize;
    final visitedRight = [false] * rightSize;

    final Queue<int> queue = Queue();

    for (int i = 0; i < leftSize; i++) {
      if (!visitedLeft[i]) {
        visitedLeft[i] = true;
        queue.add(i);

        while (queue.isNotEmpty) {
          int currentLeft = queue.removeFirst();

          for (int neighbor in leftEdges[currentLeft]) {
            if (!visitedRight[neighbor]) {
              visitedRight[neighbor] = true;
              queue.add(neighbor);
            } else {
              return false; // Found an edge connecting nodes of same color
            }
          }
        }
      }
    }

    return true;
  }
}

