        dists[i][j] = adjacencyMatrix[i][j];
      }
    }
  }

  // Floyd-Warshall algorithm: iterate over all intermediate nodes k.
  for(int k = 0; k < n; ++k){
    for(int i = 0; i < n; ++i){
      for(int j = 0; j < n; ++j){
        // If we can go from i to k and then k to j at a cheaper cost than going directly from i to j, update the path.
        if(dists[k][j].isFinite && dists[i][k].isFinite && dists[i][k] + dists[k][j] < dists[i][j]){
          dists[i][j] = dists[i][k] + dists[k][j];
        }
      }
    }
  }

