  bool get isFull => _data.length == maxSize;
  void push(T value) {
    if (isFull) throw Exception("Stack overflow");
    _data.add(value);
  }

  T pop() {
    if (isEmpty) throw Exception("Underflow");
    var item = _data.last;
    _data.removeLast();
    return item;
  }

