class Solution {
  List<int> primes = [2, 3];

  void _sieve() {
    int limit = sqrt(10000).ceil(); // We only need up to the square root of the max input
    for (int i = 4; i < limit * limit; i++) {
      if (!primes.contains(i)) continue;
      for (int j = i * i; j < limit * limit && j % i == 0; j += i) {
        primes.add(j);
      }
    }
  }

  bool isPrime(int num) {
    if (num <= 1) return false;

    // Build sieve on first call or after a reset. 
    // This simplifies logic inside loop and ensures data exists before use.
    if (primes.isEmpty || primes.last < num) _sieve(); 

    for (int p in primes) {
      if (p > num / p) break; // Optimization check
      if (num % p == 0) {
        if (p == num) return true; // Prime found directly via division
        return false;              // Found a divisor -> not prime
      }
    }
    return true;
  }
}

