void main() {
  final double a = sqrt(2);

  int digitsCount;

  do {
    // Calculate the number of digits in floor(a) by comparing with powers of ten.
    var powerOfTen = BigInt.one;
    while (BigInt.from(powerOfTen.toDouble()) < BigInt.from(floor(a))) {
      powerOfTen *= 10;
    }

    // Count how many times we multiplied to get from 1 to this threshold, which equals digit count - 1.
    digitsCount = log2(BigInt.from(powerOfTen.toDouble()).toInteger().bitLength).floor();

